  "fields": {
    "7": {
      "id": "7",
      "identity": 7,
      "type": "published_quran",
      "text": "بی‌گمان، الله به ‌اندازۀ ذره‌ای [به بندگانش] ستم نمی‌کند",
      "parent_id": "Q:4:40:PersianRowwad1.1.3",
      "source_cp": [
        0,
        56
      ],
      "source_utf16": [
        0,
