      "full_parent_sha256_utf8": "d3dbf81242773e7505f116b1c2a42ba909963841506a58e1207f0834ac44fd69",
      "verse": "4:40"
    },
    "8": {
      "id": "8",
      "identity": 8,
      "type": "published_quran",
      "text": "یقیناً الله هیچ ستمی به مردم نمی‌کند؛ ولی مردم [هستند که با شرک و نافرمانی] به خویشتن ستم می‌کنند.",
      "parent_id": "Q:10:44:PersianRowwad1.1.3",
      "source_cp": [
        0,
        98
      ],
      "source_utf16": [
        0,
        98
      ],
      "full_parent_sha256_utf8": "d012035347836476ffc16ef11816d2983ddd231b28f608ed829e0596ddd761bd",
      "verse": "10:44"
    },
    "9": {
      "id": "9",
      "identity": 9,
      "type": "published_quran",
      "text": "و پروردگارت به هیچ کسی ستم نمی‌کند",
      "parent_id": "Q:18:49:PersianRowwad1.1.3",
      "source_cp": [
        277,
