      "verse": "18:49"
    },
    "10": {
      "id": "10",
      "identity": 10,
      "type": "published_quran",
      "text": "الله ستمی برای بندگانش نمی‌خواهد",
      "parent_id": "Q:40:31:PersianRowwad1.1.3",
      "source_cp": [
        80,
