      "verse": "40:31"
    },
    "11": {
      "id": "11",
      "identity": 11,
      "type": "published_quran",
      "text": "هر کس کاری شایسته كند، به سود خودِ اوست؛ و هر کس بدى كند، به زیان خویش بد كرده است؛ و پروردگار تو هرگز به بندگان ستم نمی‌کند.",
      "parent_id": "Q:41:46:PersianRowwad1.1.3",
      "source_cp": [
        0,
        125
      ],
      "source_utf16": [
        0,
        125
      ],
      "full_parent_sha256_utf8": "702379d262cb3438df49de4de66602c40f39eb4d6dacb4afa0c08f2d904057ae",
      "verse": "41:46"
    },
    "12": {
      "id": "12",
      "identity": 12,
      "type": "published_quran",
      "text": "فرمانِ مجازات، نزد من تغییرپذیر نیست؛ و الله [در کیفر و پاداش] به بندگانش ستم نمی‌کند».",
      "parent_id": "Q:50:29:PersianRowwad1.1.3",
      "source_cp": [
        0,
        87
      ],
      "source_utf16": [
        0,
