      "full_parent_sha256_utf8": "e1d41abcf30f43b359456d0e68eb84e52addd5eb7de505ea6f6acd0e83b79b82",
      "verse": "46:3"
    },
    "15": {
      "id": "15",
      "identity": 15,
      "type": "published_quran",
      "text": "الله به عدالت داوری مى‌كند؛ و معبودانى كه [مشركان] به جاى الله عبادت می‌کنند، هیچ گونه [حق] داوری ندارند. به راستی که الله شنوای بیناست.",
      "parent_id": "Q:40:20:PersianRowwad1.1.3",
      "source_cp": [
        0,
        136
      ],
      "source_utf16": [
        0,
        136
      ],
      "full_parent_sha256_utf8": "369bfa0cecb18b19e67a87984a3dc5a74a7e0375bfc3a6b97b367dfecf132185",
      "verse": "40:20"
    },
    "16": {
      "id": "16",
      "identity": 16,
      "type": "published_quran",
      "text": "در حقیقت، الله [شما را] به عدالت و نیکوکاری و بخشش به خویشاوندان فرمان مى‌دهد و از فحشا و زشت‌کاری و سرکشی نهى مى‌كند. او شما را پند مى‌دهد؛ باشد كه پند گیرید.",
      "parent_id": "Q:16:90:PersianRowwad1.1.3",
      "source_cp": [
        0,
        159
      ],
      "source_utf16": [
        0,
        159
      ],
      "full_parent_sha256_utf8": "066afa2bc8b31ddb8e6b001fab5186f7372905650548fa23dada4571de0a4156",
      "verse": "16:90"
    },
    "17:55:7": {
      "id": "17:55:7",
      "identity": 17,
      "type": "published_quran",
      "text": "و آسمان را برافراشت و میزان [عدالت را در زمین] برقرار نمود.",
      "parent_id": "Q:55:7:PersianRowwad1.1.3",
