      "verse": "55:9"
    },
    "18": {
      "id": "18",
      "identity": 18,
      "type": "published_quran",
      "text": "و سخن پروردگارت [= قرآن] با راستى [در گفتار] و عدل [در احکام] به حد تمام و کمال رسید",
