    "Q:16:90:PersianRowwad1.1.3": {
      "type": "published_quran_parent",
      "publisher": "QuranEnc.com; Rowwad Translation Center",
      "verse": "16:90",
      "url": "https://quranenc.com/api/v1/translation/aya/persian_ih/16/90",
      "raw_response_sha256": "e9da7135a16e33eb0f196809d98ceabe6e8a3497e198c385282e3e4dd2d00f65",
